\begin{proof}
Let $z=\{z_{e}\}_{e\in \binom{U}{2}}$ be the random variables in \Cref{lem:KLM-theorem} with the parameter $p$ defined by  $p=\Psi(|U|,m,d)^{1/d}$, and write $f(y)=\sum_{M\in\calM_{U,d}}a_{M}y^{M}$. We define $g\in \calC^{U,m,d}$ to be $g(y):=\sum_{M\in\calM_{U,d}}|a_{M}|y^{M}$. 
Expanding, we get 
\[\E_{y\in\Omega^{U,m}}\left[f(y)^{2q}\right]=
\sum_{M_{1},\dots,M_{2q}\in \calM_{U,d}}
\E_{y\in\Omega^{U,m}}\left[\prod_{i=1}^{2q}y^{M_{i}}\right]\prod_{i=1}^{2q}a_{M_i}.\]
For each tuple of matchings $M_{1},\dots,M_{2q}\in\calM_{U,d}$, the expectation $\E_{y\in\Omega^{U,m}}\left[\prod_{i=1}^{2q}y^{M_{i}}\right]$ evaluates to either 0 (if some edge appears an odd number of times in these matchings) or some positive value. So replacing all $a_{i}$'s on the right hand side with their absolute values does not decrease the total value of the sum. We therefore have
\begin{align}
\E_{y\in\Omega^{U,m}}\left[f(y)^{2q}\right]&\leq \sum_{M_{1},\dots,M_{2q}\in \calM_{U,d}}
\E_{y\in\Omega^{U,m}}\left[\prod_{i=1}^{2q}y^{M_{i}}\right]\prod_{i=1}^{2q}|a_{M_i}|
\nonumber\\
&=\sum_{(M_{1},\dots,M_{2q})\in \textsf{Even}}
\Psi\left(|U|,m,\left|\bigcup_{i=1}^{2q}M_{i}\right|\right)\cdot\prod_{i=1}^{2q}|a_{M_i}|&(\text{by \Cref{def:Psi}})\nonumber\\
&\leq \sum_{(M_{1},\dots,M_{2q})\in \textsf{Even}}
p^{\left|\bigcup_{i=1}^{2q}M_{i}\right|}\cdot \prod_{i=1}^{2q}|a_{M_i}|&(\text{by \Cref{prop:approximate-product}(2)})\notag\\
&= \E_{z}\left[\widetilde{g}(z)^{2q}\right],\label{eq:assume-nonnegative-coefficients}
\end{align}
where $\textsf{Even}$ denotes the collection of tuples $(M_{1},\dots,M_{2q})\in \calM_{U,d}$ such that every edge appears an even number of times in these matchings.

Using \Cref{prop:formal-compatibility}, for $S\in\calM_{U,\leq d}$ we also have
\begin{align}
\E_{y\in\Omega^{U,m}_{\setminus S}}\left[D_{S}[f](y)^{2}\right]
=\E_{y\in\Omega^{U,m}_{\setminus S}}\left[\widetilde{D_{S}}\widetilde{f}(y)^{2}\right]
&=\E_{y\in\Omega^{U,m}_{\setminus S}}\left[\left(\sum_{M\in\calM_{U,d},\, M\supseteq S}a_{M}y^{M\setminus S}\right)^{2}\right] \nonumber\\
&=\sum_{M\in\calM_{U,d},\, M\supseteq S}a_{M}^{2}\cdot \Psi\Big(|U\setminus N(S)|,m-|S|,d-|S|\Big)\nonumber\\
&=\Psi(|U|,m,d)\cdot\Psi(|U|,m,|S|)^{-1}\cdot\sum_{M\in\calM_{U,d},\, M\supseteq S}a_{M}^{2}.\nonumber\\
&\geq p^{d}(2p)^{-|S|}\sum_{M\in\calM_{U,d},\, M\supseteq S}a_{M}^{2}\notag\\
&=2^{-|S|}\E_{z}\left[\widetilde{D_{S}}\widetilde{g}(z)^{2}\right],\label{eq:substitute-2} 
\end{align}
where the fifth transition uses~\Cref{prop:approximate-product}(1). Plugging \eqref{eq:assume-nonnegative-coefficients} and \eqref{eq:substitute-2} into \Cref{lem:KLM-theorem} yields
\begin{equation}\label{eq:derivative-based-untidied}
\left\|f\right\|_{2q}^{2q}\leq \rho^{-2dq}\sum_{S\in\calM_{U,\leq d}}\beta^{2q|S|}(2q)^{-q|S|}\cdot p^{|S|}\cdot2^{q|S|}\left\|D_{S}f\right\|_{2}^{2q}
= \rho^{-2dq}\sum_{S\in\calM_{U,\leq d}}\beta^{2q|S|}q^{-q|S|}\cdot p^{|S|}\cdot\left\|D_{S}f\right\|_{2}^{2q},
\end{equation}
where $\beta:=\rho\sqrt{2q}\left(1+\frac{4(q-1)}{\ln(\rho^{-1}(2q)^{-1/2})}\right)$ and $\rho$ is given by \eqref{eq:rho-formula}. 
Using $\rho^{-1}(2q)^{-1/2}\geq 4$ we get $\beta\leq \rho\sqrt{2q}\cdot 4q$. Now the other upper bound $\rho\leq \frac{1}{4\sqrt{2}}q^{-1}r^{-\frac{q-1}{q}}$ yields $\beta^{2q}q^{-q}r^{2q-2}\leq 1$. Plugging back into \eqref{eq:derivative-based-untidied}, we get
\begin{align}
\left\|f\right\|_{2q}^{2q}&\leq \rho^{-2dq}\sum_{S\in\calM_{U,\leq d}} p^{|S|}\cdot\left\|D_{S}f\right\|_{2}^{2}\cdot\left(r^{-|S|}\left\|D_{S}f\right\|_{2}\right)^{2q-2}\nonumber\\
&\leq \rho^{-2dq}\left(\sum_{S\in\calM_{U,\leq d}} p^{|S|}\cdot\left\|D_{S}f\right\|_{2}^{2}\right)\cdot\max_{S\in\calM_{U,\leq d}}\left(r^{-|S|}\left\|D_{S}f\right\|_{2}\right)^{2q-2}.\label{eq:derivative-based-tidied}
\end{align}
Now using \Cref{prop:approximate-product}(1) again, we have
\begin{align*}
\sum_{S\in\calM_{U,\leq d}} p^{|S|}\cdot\left\|D_{S}f\right\|_{2}^{2}&\leq \sum_{S\in\calM_{U,\leq d}} \Psi(|U|,m,|S|)\cdot\left\|D_{S}f\right\|_{2}^{2}\\
&= \sum_{S\in\calM_{U,\leq d}}\Psi(|U|,m,|S|)\cdot\E_{y\in\Omega^{U,m}_{\setminus S}}\left[\left(\sum_{M\in\calM_{U,d},\,M\supseteq S}a_{M}y^{M\setminus S}\right)^{2}\right]\\
&=\sum_{S\in\calM_{U,\leq d}}\Psi(|U|,m,|S|)\Psi\Big(|U\setminus N(S)|,m-|S|,d-|S|\Big)
\sum_{\substack{M\in\calM_{U,d}\\ M\supseteq S}}a_{M}^{2}\\
&=\sum_{S\in\calM_{U,\leq d}}\Psi(|U|,m,d)\sum_{\substack{M\in\calM_{U,d}\\ M\supseteq S}}a_{M}^{2}=2^{d}\sum_{M\in\calM_{U,d}}\Psi(|U|,m,d)\cdot a_{M}^{2}\\
&=2^{d}\E_{y\in\Omega^{U,m}}\left[\left(\sum_{M\in\calM_{U,d}}a_{M}y^{M}\right)^{2}\right]=2^{d}\left\|f\right\|_{2}^{2}.
\end{align*}
Plugging the above into \eqref{eq:derivative-based-tidied} yields the conclusion.
\end{proof}
